--liquibase formatted sql

--changeset quiz-bank-round2:1
-- The CEFR level at which learners meet each form: gap items testing a form above the learner's level wait.
CREATE TABLE IF NOT EXISTS morph_form_levels (morph_code TEXT PRIMARY KEY, cefr_level TEXT NOT NULL);
-- Hand-picked words a learner could confuse with a word (same field or look-alike, never a synonym):
-- the first wrong options in its meaning questions.
CREATE TABLE IF NOT EXISTS word_quiz_confusables (
    word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE,
    distractor_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (word_id, distractor_id)
);

